class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


class Solution:
    def remove_leaf_nodes(self, root, target):
        """Remove all leaf nodes with the specified target value from the tree."""
        while self.has_leaf(root, target):
            root = self.remove_leaf(target, root)
        return root

    def remove_leaf(self, target, node):
        """Recursively remove leaf nodes that match the target."""
        if node is None:
            return node
        # Check if the current node is a leaf and matches the target
        if node.val == target and node.left is None and node.right is None:
            return None

        # Recursively check the left and right children
        if node.left is not None:
            node.left = self.remove_leaf(target, node.left)
        if node.right is not None:
            node.right = self.remove_leaf(target, node.right)

        return node

    def has_leaf(self, node, target):
        """Check if the tree has a leaf node with the target value."""
        if node is None:
            return False
        if node.left is None and node.right is None and node.val == target:
            return True
        # Check both children for a leaf with the target value
        return self.has_leaf(node.left, target) or self.has_leaf(node.right, target)
